contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: amount is how much Ether to forward to c.go
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to send");

        // observe owner and c balance before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balCBefore = address(c).balance;

        bool reverted;
        // Top-level state-changing call on c
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balCAfter = address(c).balance;

        // General property: for all inputs, either the call reverted, or the owner is unchanged
        // and c's balance is zero after a successful call.
        assert(reverted || (ownerAfter == ownerBefore && balCAfter == 0));
    }

    // receive to accept Ether forwarded from c if needed
    receive() external payable {}
}

